import{_ as a,c as t,o as i,a2 as e}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"getPortalDeposit","description":"Read the SDK\'s note evidence for one portal.","frontmatter":{"editLink":false,"rawMarkdown":"# getPortalDeposit\\n\\nRead the SDK\'s note evidence for one portal. A service shielding receipt is not a committed private balance.\\n\\n## Import\\n\\n```ts\\nimport { getPortalDeposit } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await getPortalDeposit({ portal, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction getPortalDeposit(parameters: GetPortalDepositParameters): Promise<PortalDepositSnapshot>\\n```\\n\\n## Returns\\n\\n`Promise<PortalDepositSnapshot>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `portal`\\n\\n- **Type:** `MatchedPortalRecord`\\n- **Required:** yes\\n\\nAn entry portal resolved by findPortal for this account. Never correlate deposits by ticker or amount.\\n\\n```ts\\nconst result = await getPortalDeposit({\\n  portal, // [!code focus]\\n});\\n```\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account that owns the portal. Defaults to the active account.\\n\\n```ts\\nconst result = await getPortalDeposit({\\n  portal,\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nAborts the read.\\n\\n```ts\\nconst result = await getPortalDeposit({\\n  portal,\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await getPortalDeposit({\\n  portal,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/getPortalDeposit.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/getPortalDeposit.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/getPortalDeposit.md","rawMarkdownTitle":"getPortalDeposit","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/getPortalDeposit.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"getPortalDeposit"},"relativePath":"sdk/actions/views/getPortalDeposit.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/views/getPortalDeposit.md"};function o(r,s,l,p,h,c){return i(),t("div",null,[...s[0]||(s[0]=[e("",34)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
